<?php
declare(strict_types=1);
require_once __DIR__.'/../config/bootstrap.php';$user=require_login($pdo);$pageTitle=t('finance_customer.billing');$error='';$success='';
$profile=finance_billing_profile($pdo,(int)$user['id'])??['legal_name'=>$user['full_name'],'address_line1'=>'','address_line2'=>'','postal_code'=>$user['zip'],'city'=>$user['city'],'country_code'=>$user['country_code']??'DE','vat_id'=>''];
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();try{$profile=$_POST;finance_save_profile($pdo,(int)$user['id'],$_POST);$success=t('finance_customer.saved');}catch(InvalidArgumentException $e){http_response_code(422);$error=$e->getMessage();}}
include __DIR__.'/../includes/header.php';?>
<main class="container"><div class="page-heading"><p class="eyebrow"><?=h(t('finance_customer.billing_kicker'))?></p><h1><?=h(t('finance_customer.billing_heading'))?></h1><p><?=h(t('finance_customer.private'))?></p></div><section class="panel"><?php if($error):?><p class="notice error" role="alert"><?=h($error)?></p><?php endif;?><?php if($success):?><p class="notice success" role="status"><?=h($success)?></p><?php endif;?>
<form method="post" class="form-grid"><?=csrf_field()?><?php foreach(['legal_name','address_line1','address_line2','postal_code','city','vat_id'] as $key):?><label class="field"><?=h(t('finance_customer.'.$key))?><input name="<?=h($key)?>" value="<?=h($profile[$key]??'')?>" maxlength="<?=in_array($key,['postal_code','vat_id'],true)?($key==='postal_code'?16:40):150?>" <?=in_array($key,['address_line2','vat_id'],true)?'':'required'?>></label><?php endforeach;?>
<label class="field"><?=h(t('finance_customer.country'))?><select name="country_code"><?php foreach(geo_countries() as $code=>$name):?><option value="<?=h($code)?>" <?=($profile['country_code']??'DE')===$code?'selected':''?>><?=h($name)?></option><?php endforeach;?></select></label><p><?=h(t('finance_customer.vat_help'))?></p><button class="button" type="submit"><?=h(t('finance_customer.save'))?></button></form></section><a class="button secondary" href="/user/invoices.php"><?=h(t('finance_customer.title'))?></a></main><?php include __DIR__.'/../includes/footer.php';?>
